def convert_usernames_to_new_format(apps, schema_editor):
    """
    Convert existing usernames to new format: prefix#0000
    """
    CustomUser = apps.get_model("authenticationApp", "CustomUser")

    # Get all users that don't already have the new format
    users_to_convert = []
    for user in CustomUser.objects.all():
        if "#" not in user.username:  # Skip users already in new format
            users_to_convert.append(user)

    if not users_to_convert:
        return  # Nothing to convert

    print(f"Converting {len(users_to_convert)} usernames to new format...")

    converted_count = 0
    for user in users_to_convert:
        try:
            old_username = user.username
            new_username = generate_username_from_email(CustomUser, user.email)

            if new_username:
                user.username = new_username
                user.save()
                print(f"Converted: {user.email} | {old_username} -> {new_username}")
                converted_count += 1
            else:
                print(f"Warning: Could not generate username for {user.email}")

        except Exception as e:
            print(f"Error converting user {user.email}: {str(e)}")

    print(f"Successfully converted {converted_count} usernames!")


def generate_username_from_email(model_class, email):
    """
    Generate username from email in format: prefix#0000
    """
    if not email:
        return None

    # Extract email prefix (part before @)
    email_prefix = email.split("@")[0].lower()

    # Remove numbers and special characters, keep only letters
    clean_prefix = "".join(char for char in email_prefix if char.isalpha())

    # Take up to 6 characters for the base username
    base_username = clean_prefix[:6] if len(clean_prefix) >= 6 else clean_prefix

    # Generate 4 random digits
    random_digits = "".join(random.choices(string.digits, k=4))

    # Create username with # separator
    generated_username = f"{base_username}#{random_digits}"

    # Ensure uniqueness - regenerate digits if username already exists
    max_attempts = 100
    attempts = 0
    while (
        model_class.objects.filter(username=generated_username).exists()
        and attempts < max_attempts
    ):
        random_digits = "".join(random.choices(string.digits, k=4))
        generated_username = f"{base_username}#{random_digits}"
        attempts += 1

    return generated_username


